import{sorted,mean}from'./stats.js';import{RULES,confidence}from'./config.js';
export function analyzeRetention(rows){const data=sorted(rows),missing=data.filter(r=>!Array.isArray(r.members));if(!data.length||missing.length){const aggregates=data.filter(r=>r.returning_members!=null&&r.returning_members<=r.attendance&&(r.new_members==null||r.new_members+r.returning_members===r.attendance)&&r.attendance>0);return{available:false,sampleSize:data.length,missingMeetings:missing.length,excludedRows:missing.map(r=>({id:r.id,reason:'Member IDs missing or invalid.'})),aggregate:aggregates.length?{sampleSize:aggregates.length,returningShare:aggregates.reduce((s,r)=>s+r.returning_members,0)/aggregates.reduce((s,r)=>s+r.attendance,0),label:'Reported returning-member share; not cohort retention'}:null,warnings:['Member-level attendance data is required to calculate true retention. Missing IDs disable cohort analysis instead of treating missing members as absent.'],confidence:confidence(0)}}
const seen=new Map(),perMeeting=[];for(let i=0;i<data.length;i++){const r=data[i],newMembers=r.members.filter(id=>!seen.has(id)).length;perMeeting.push({id:r.id,date:r.date,name:r.name,attendance:r.attendance,newMembers,returning:r.attendance-newMembers,returningShare:r.attendance?(r.attendance-newMembers)/r.attendance:null});for(const id of r.members){if(!seen.has(id))seen.set(id,[]);seen.get(id).push(i)}}
const histories=[...seen.values()],eligible=histories.filter(a=>a[0]+RULES.followup<data.length),returned=eligible.filter(a=>a.some(j=>j>a[0]&&j<=a[0]+RULES.followup)),nextEligible=histories.filter(a=>a[0]+1<data.length),nextReturned=nextEligible.filter(a=>a.includes(a[0]+1)),repeat=histories.filter(a=>a.length>=2).length,consistent=histories.filter(a=>a.length>=3).length;
const cohorts=data.map((r,i)=>{const members=histories.filter(a=>a[0]===i);return{id:r.id,date:r.date,name:r.name,n:members.length,returned:members.filter(a=>a.some(j=>j>i&&j<=i+RULES.followup)).length,complete:i+RULES.followup<data.length}}).filter(c=>c.n);
const shares=perMeeting.filter(r=>r.returningShare!=null),recent=shares.slice(-3),previous=shares.slice(-6,-3);return{available:true,sampleSize:data.length,unique:seen.size,repeat,repeatRate:seen.size?repeat/seen.size:null,consistent,consistentRate:seen.size?consistent/seen.size:null,eligible:eligible.length,returned:returned.length,rate:eligible.length?returned.length/eligible.length:null,nextMeetingRate:nextEligible.length?nextReturned.length/nextEligible.length:null,nextEligible:nextEligible.length,nextReturned:nextReturned.length,perMeeting,cohorts,trend:recent.length===3&&previous.length===3?{recent:mean(recent.map(r=>r.returningShare)),previous:mean(previous.map(r=>r.returningShare)),percentagePoints:(mean(recent.map(r=>r.returningShare))-mean(previous.map(r=>r.returningShare)))*100}:null,warnings:['Newcomer means first appearance in these records. Recent cohorts without three follow-up meetings are excluded from the return rate. Returning share is not the same as cohort retention.'],confidence:confidence(eligible.length)}}
export function retention(rows){const r=analyzeRetention(rows);return r.available?r:null}
